WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CONTROL_DE_APRIETE_01' AND v.numero=1), d(titulo,orden) AS (VALUES ('CONTROL DE APRIETE - ALSTOM',1),('LISTA DE INSTRUMENTOS :',2),('OBSERVACIONES:',3),('PERSONAL:',4)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.titulo,d.orden FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CONTROL_DE_APRIETE_01' AND v.numero=1), s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)), f AS (SELECT jsonb_agg(jsonb_build_object('coche',c,'bogie',b,'eje',n,'amortiguador_vertical_1','','amortiguador_transversal','','biela_pos_3a','','biela_320nm','','longitud_biela_mm','','diferir_max_4mm','','medida_16_mm','','amortiguador_vertical_2','','varilla_nivelacion','','suspension_primaria','') ORDER BY n) filas FROM unnest(ARRAY['MA1','MA1','MA1','MA1','MB1','MB1','MB1','MB1','MB3','MB3','MB3','MB3','R','R','R','R','MB2','MB2','MB2','MB2','MA2','MA2','MA2','MA2']) WITH ORDINALITY x(c,n) JOIN unnest(ARRAY['PB3','PB3','PB4','PB4','PB6','PB6','PB2','PB2','PB6','PB6','PB2','PB2','TB1','TB1','TB2','TB2','PB2','PB2','PB6','PB6','PB4','PB4','PB3','PB3']) WITH ORDINALITY y(b,n) USING(n)), d(titulo,codigo,etiqueta,tipo,orden,config) AS (VALUES ('CONTROL DE APRIETE - ALSTOM','fecha','FECHA:','fecha',1,'{}'),('CONTROL DE APRIETE - ALSTOM','puntos_apriete','CONTROL DE APRIETE - ALSTOM','tabla',2,jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','coche','etiqueta','COCHE'),jsonb_build_object('codigo','bogie','etiqueta','BOGIE/SERIE'),jsonb_build_object('codigo','eje','etiqueta','EJE'),jsonb_build_object('codigo','amortiguador_vertical_1','etiqueta','AMORTIGUADOR VERTICAL pos.2 / 69 Nm'),jsonb_build_object('codigo','amortiguador_transversal','etiqueta','AMORTIGUADOR TRANSVERSAL pos.6 / 69 Nm'),jsonb_build_object('codigo','biela_pos_3a','etiqueta','BIELA pos.3A / 85 Nm'),jsonb_build_object('codigo','biela_320nm','etiqueta','BIELA / 320 Nm'),jsonb_build_object('codigo','longitud_biela_mm','etiqueta','Long. Biela (mm)'),jsonb_build_object('codigo','diferir_max_4mm','etiqueta','Diferir Max. 4mm'),jsonb_build_object('codigo','medida_16_mm','etiqueta','16 +/- 1 mm'),jsonb_build_object('codigo','amortiguador_vertical_2','etiqueta','AMORTIGUADOR VERTICAL pos.2 / 69 Nm'),jsonb_build_object('codigo','varilla_nivelacion','etiqueta','VARILLA DE NIVELACIÓN / 40 Nm'),jsonb_build_object('codigo','suspension_primaria','etiqueta','SUSPENSION PRIMARIA / 250 Nm')),'filasIniciales',(SELECT filas FROM f))),('LISTA DE INSTRUMENTOS :','instrumentos','LISTA DE INSTRUMENTOS :','tabla',1,'{"columnas":[{"codigo":"codigo","etiqueta":"Código"},{"codigo":"descripcion","etiqueta":"Descripción"},{"codigo":"modelo","etiqueta":"Modelo / Marca"},{"codigo":"fecha_calibracion","etiqueta":"Fecha de Calibración"},{"codigo":"vencimiento","etiqueta":"Fecha de Vencimiento de Calibración"},{"codigo":"observaciones","etiqueta":"Observaciones"}],"filasIniciales":[{},{},{},{},{},{},{}]}'),('OBSERVACIONES:','observaciones','OBSERVACIONES:','texto',1,'{"multilinea":true}'),('PERSONAL:','tecnicos','TÉCNICOS','tabla',1,'{"columnas":[{"codigo":"tecnico","etiqueta":"TÉCNICO"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"tecnico":"TÉCNICO A:"},{"tecnico":"TÉCNICO B:"},{"tecnico":"TÉCNICO C:"},{"tecnico":"TÉCNICO D:"},{"tecnico":"TÉCNICO E:"},{"tecnico":"TÉCNICO F:"},{"tecnico":"TÉCNICO G:"},{"tecnico":"TÉCNICO O:"},{"tecnico":"TÉCNICO P:"},{"tecnico":"TÉCNICO Q:"},{"tecnico":"TÉCNICO R:"},{"tecnico":"TÉCNICO S:"},{"tecnico":"TÉCNICO T:"},{"tecnico":"TÉCNICO U:"}]}'),('PERSONAL:','responsables','RESPONSABLES','tabla',2,'{"columnas":[{"codigo":"responsable","etiqueta":"RESPONSABLE"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"responsable":"RESPONSABLE MTTO :"},{"responsable":"RESPONSABLE 01:"},{"responsable":"RESPONSABLE 02"},{"responsable":"RESPONSABLE 03"},{"responsable":"RESPONSABLE 04"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.codigo,d.etiqueta,d.tipo,d.orden,d.config FROM d JOIN s ON s.titulo=d.titulo ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
